    });

    test("unknown tool is a protocol error", async () => {
      const { body } = await callTool(url, "no_such_tool", {});
      assert.equal(body.error.code, -32602);
    });

    test("origin validation", async () => {
      const bad = await rpc(url, "tools/list", {}, { headers: { Origin: "http://evil.example" } });
      assert.equal(bad.status, 403);
      const wrongPort = await rpc(url, "tools/list", {}, { headers: { Origin: "http://localhost:1" } });
      assert.equal(wrongPort.status, 403);
