    test("GET/DELETE are 405, notifications 202, bad JSON 400, bad Accept 406", async () => {
      assert.equal((await fetch(url)).status, 405);
      assert.equal((await fetch(url, { method: "DELETE" })).status, 405);

      const notif = await fetch(url, {
        method: "POST",
