      });
      assert.equal(bad.status, 400);
      assert.equal((await bad.json()).error.code, -32700);

      const accept = await rpc(url, "tools/list", {}, { headers: { Accept: "application/json" } });
      assert.equal(accept.status, 406);
    });

    test("results carry serverInfo and ignore session headers", async () => {
      const { res } = await post(url, "tools/list", {}, { headers: { "Mcp-Session-Id": "abc" } });
      assert.equal(res.status, 200);
      assert.equal(res.headers.get("mcp-session-id"), null);
      const body = await res.json();
      assert.deepEqual(body.result._meta["io.modelcontextprotocol/serverInfo"], { name: "field-notes", version: "1.0.0" });
    });
  });
});

describe("graceful shutdown", () => {
  test("open subscriptions receive a completion result", async () => {
    const s = await startServer();
    try {
      const sub = await listen(s.url, { resourceSubscriptions: ["notes://index"] });
      assert.equal((await sub.reader.next())!.method, "notifications/subscriptions/acknowledged");
      s.proc.kill("SIGTERM");
      const done = await sub.reader.next(3000);
      assert.equal(done!.id, sub.id);
      assert.equal(done!.result.resultType, "complete");
      assert.equal(done!.result._meta["io.modelcontextprotocol/subscriptionId"], sub.id);
    } finally {
      await stopServer(s);
    }
  });
});

