        });
        assert.ok(await n3Watcher.reader.quiet(200), "n3 watcher must not hear about index changes");

        // Delete n2 via the confirmation flow.
        const first = await callTool(url, "delete_note", { id: "n2" }, { caps: FORM_CAPS });
        const key = Object.keys(first.body.result.inputRequests)[0]!;
        const del = await callTool(
          url,
          "delete_note",
          { id: "n2" },
          { caps: FORM_CAPS },
          {
            inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
            requestState: first.body.result.requestState,
          },
        );
        assert.equal(del.body.result.content[0].text, "Deleted note n2");
        const uris = [(await indexWatcher.reader.next())!.params.uri, (await indexWatcher.reader.next())!.params.uri];
        assert.deepEqual(uris.sort(), ["notes://index", "notes://notes/n2"]);
        assert.ok(await n3Watcher.reader.quiet(200));
      } finally {
        indexWatcher.close();
        n3Watcher.close();
      }
    });

    test("listen without a notifications filter is invalid params", async () => {
      const { body } = await rpc(url, "subscriptions/listen", {});
      assert.equal(body.error.code, -32602);
    });
  });

  describe("transport and protocol validation", () => {
    test("unsupported protocol version", async () => {
      const { status, body } = await rpc(url, "tools/list", {}, {
        headers: { "MCP-Protocol-Version": "2025-11-25" },
        rawParams: { _meta: { ...meta(), "io.modelcontextprotocol/protocolVersion": "2025-11-25" } },
      });
      assert.equal(status, 400);
      assert.equal(body.error.code, -32022);
      assert.deepEqual(body.error.data, { supported: ["2026-07-28"], requested: "2025-11-25" });
    });

    test("initialize from a legacy client names the supported versions", async () => {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json, text/event-stream" },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "initialize",
          params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "old", version: "1" } },
        }),
      });
      assert.equal(res.status, 400);
      const body = await res.json();
      assert.equal(body.error.code, -32022);
      assert.deepEqual(body.error.data.supported, ["2026-07-28"]);
    });

    test("missing required _meta fields are -32602 with 400", async () => {
      const noMeta = await rpc(url, "tools/list", {}, { rawParams: {} });
      assert.equal(noMeta.status, 400);
      assert.equal(noMeta.body.error.code, -32602);
      const noCaps = await rpc(url, "tools/list", {}, {
        rawParams: { _meta: { "io.modelcontextprotocol/protocolVersion": VERSION } },
      });
      assert.equal(noCaps.status, 400);
      assert.equal(noCaps.body.error.code, -32602);
    });

    test("header/body mismatches are -32020 with 400", async () => {
      const cases: Record<string, string | undefined>[] = [
        { "MCP-Protocol-Version": undefined },
        { "MCP-Protocol-Version": "2099-01-01" },
        { "Mcp-Method": undefined },
        { "Mcp-Method": "tools/call" },
      ];
      for (const headers of cases) {
        const { status, body } = await rpc(url, "tools/list", {}, { headers });
        assert.equal(status, 400, JSON.stringify(headers));
        assert.equal(body.error.code, -32020, JSON.stringify(headers));
      }
      const noName = await rpc(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": undefined } });
      assert.equal(noName.body.error.code, -32020);
      const wrongName = await rpc(url, "resources/read", { uri: "notes://index" }, { headers: { "Mcp-Name": "notes://notes/n1" } });
      assert.equal(wrongName.status, 400);
      assert.equal(wrongName.body.error.code, -32020);
      const b64Name = await rpc(url, "resources/read", { uri: "notes://index" }, {
        headers: { "Mcp-Name": `=?base64?${Buffer.from("notes://index").toString("base64")}?=` },
      });
      assert.equal(b64Name.status, 200);
      assert.ok(b64Name.body.result);
    });

    test("unknown methods are 404 / -32601", async () => {
      for (const method of ["ping", "resources/subscribe", "logging/setLevel", "nope"]) {
        const { status, body } = await rpc(url, method);
        assert.equal(status, 404, method);
        assert.equal(body.error.code, -32601, method);
      }
    });

    test("unknown tool is a protocol error", async () => {
      const { body } = await callTool(url, "no_such_tool", {});
      assert.equal(body.error.code, -32602);
    });

    test("origin validation", async () => {
      const bad = await rpc(url, "tools/list", {}, { headers: { Origin: "http://evil.example" } });
      assert.equal(bad.status, 403);
      const wrongPort = await rpc(url, "tools/list", {}, { headers: { Origin: "http://localhost:1" } });
      assert.equal(wrongPort.status, 403);
      for (const origin of [`http://localhost:${server.port}`, `http://127.0.0.1:${server.port}`]) {
        const ok = await rpc(url, "tools/list", {}, { headers: { Origin: origin } });
        assert.equal(ok.status, 200, origin);
      }
    });

    test("GET/DELETE are 405, notifications 202, bad JSON 400, bad Accept 406", async () => {
      assert.equal((await fetch(url)).status, 405);
      assert.equal((await fetch(url, { method: "DELETE" })).status, 405);

      const notif = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json, text/event-stream",
          "MCP-Protocol-Version": VERSION,
        },
        body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/cancelled", params: { requestId: 1 } }),
      });
      assert.equal(notif.status, 202);
      assert.equal(await notif.text(), "");

      const bad = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json, text/event-stream" },
        body: "{not json",
      });
      assert.equal(bad.status, 400);
      assert.equal((await bad.json()).error.code, -32700);

      const accept = await rpc(url, "tools/list", {}, { headers: { Accept: "application/json" } });
      assert.equal(accept.status, 406);
    });

    test("results carry serverInfo and ignore session headers", async () => {
      const { res } = await post(url, "tools/list", {}, { headers: { "Mcp-Session-Id": "abc" } });
      assert.equal(res.status, 200);
      assert.equal(res.headers.get("mcp-session-id"), null);
      const body = await res.json();
      assert.deepEqual(body.result._meta["io.modelcontextprotocol/serverInfo"], { name: "field-notes", version: "1.0.0" });
    });
  });
});

describe("graceful shutdown", () => {
  test("open subscriptions receive a completion result", async () => {
    const s = await startServer();
    try {
      const sub = await listen(s.url, { resourceSubscriptions: ["notes://index"] });
      assert.equal((await sub.reader.next())!.method, "notifications/subscriptions/acknowledged");
      s.proc.kill("SIGTERM");
      const done = await sub.reader.next(3000);
      assert.equal(done!.id, sub.id);
      assert.equal(done!.result.resultType, "complete");
      assert.equal(done!.result._meta["io.modelcontextprotocol/subscriptionId"], sub.id);
    } finally {
      await stopServer(s);
    }
  });
});

