import { after, before, describe, test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawn, type ChildProcess } from "node:child_process";
import { once } from "node:events";
import net from "node:net";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const VERSION = "2026-07-28";

type Json = Record<string, any>;

interface Server {
  proc: ChildProcess;
  port: number;
  url: string;
  stderr: () => string;
}

async function freePort(): Promise<number> {
  const srv = net.createServer();
  srv.listen(0, "127.0.0.1");
  await once(srv, "listening");
  const port = (srv.address() as net.AddressInfo).port;
  srv.close();
  await once(srv, "close");
  return port;
}

async function startServer(): Promise<Server> {
  const port = await freePort();
  const proc = spawn(process.execPath, ["dist/server.js"], {
    cwd: ROOT,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "ignore", "pipe"],
  });
  let log = "";
  proc.stderr!.setEncoding("utf8");
  await new Promise<void>((resolve, reject) => {
    proc.stderr!.on("data", (chunk: string) => {
      log += chunk;
      if (log.includes("listening")) resolve();
    });
    proc.on("exit", (code) => reject(new Error(`server exited early (${code}): ${log}`)));
  });
  return { proc, port, url: `http://127.0.0.1:${port}/mcp`, stderr: () => log };
}

async function stopServer(s: Server): Promise<void> {
  if (s.proc.exitCode !== null) return;
  s.proc.kill("SIGTERM");
  await once(s.proc, "exit");
}

let nextId = 1;

function meta(caps: Json = {}, extra: Json = {}): Json {
  return {
    "io.modelcontextprotocol/protocolVersion": VERSION,
    "io.modelcontextprotocol/clientInfo": { name: "test-client", version: "0.0.1" },
    "io.modelcontextprotocol/clientCapabilities": caps,
    ...extra,
  };
}

interface RpcOptions {
  caps?: Json;
  metaExtra?: Json;
  headers?: Record<string, string | undefined>;
  signal?: AbortSignal;
  /** Replace the whole body (headers are still derived from method/params). */
  rawParams?: Json;
}

function standardHeaders(method: string, params: Json): Record<string, string> {
  const h: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": VERSION,
    "Mcp-Method": method,
  };
  if (method === "tools/call" || method === "prompts/get") h["Mcp-Name"] = params.name;
  if (method === "resources/read") h["Mcp-Name"] = params.uri;
  if (method === "tools/call" && params.name === "add_note" && typeof params.arguments?.notebook === "string") {
    h["Mcp-Param-Notebook"] = params.arguments.notebook;
  }
  return h;
}

async function post(url: string, method: string, params: Json, opts: RpcOptions = {}) {
  const id = nextId++;
  const fullParams = opts.rawParams ?? { ...params, _meta: meta(opts.caps, opts.metaExtra) };
  const headers: Record<string, string> = { ...standardHeaders(method, params) };
  for (const [k, v] of Object.entries(opts.headers ?? {})) {
    const existing = Object.keys(headers).find((h) => h.toLowerCase() === k.toLowerCase());
    if (existing) delete headers[existing];
    if (v !== undefined) headers[k] = v;
  }
  const res = await fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params: fullParams }),
    signal: opts.signal,
  });
  return { id, res };
}

/** Parses a complete SSE body into its JSON messages. */
function parseSse(text: string): Json[] {
  return text
    .split(/\n\n/)
    .map((block) =>
      block
        .split("\n")
        .filter((l) => l.startsWith("data:"))
        .map((l) => l.slice(5).trimStart())
        .join("\n"),
    )
    .filter((d) => d !== "")
    .map((d) => JSON.parse(d));
}

/** Sends a request and returns every message received (notifications + final response). */
async function rpcAll(url: string, method: string, params: Json = {}, opts: RpcOptions = {}) {
  const { id, res } = await post(url, method, params, opts);
  const ct = res.headers.get("content-type") ?? "";
  const text = await res.text();
  const messages = ct.startsWith("text/event-stream") ? parseSse(text) : text ? [JSON.parse(text)] : [];
  const response = messages.find((m) => m.id === id);
  return { status: res.status, contentType: ct, messages, response: response as Json, id };
}

async function rpc(url: string, method: string, params: Json = {}, opts: RpcOptions = {}) {
  const r = await rpcAll(url, method, params, opts);
  return { status: r.status, body: r.response, contentType: r.contentType };
}

/** Incremental reader for a long-lived SSE stream. */
class SseReader {
  private buf = "";
  private queue: Json[] = [];
  private waiters: ((m: Json | null) => void)[] = [];
  private ended = false;

  constructor(body: ReadableStream<Uint8Array>) {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    (async () => {
      try {
        for (;;) {
          const { value, done } = await reader.read();
          if (done) break;
          this.buf += decoder.decode(value, { stream: true });
          let idx;
          while ((idx = this.buf.indexOf("\n\n")) >= 0) {
            const block = this.buf.slice(0, idx);
            this.buf = this.buf.slice(idx + 2);
            for (const m of parseSse(block + "\n\n")) this.push(m);
          }
        }
      } catch {
        // aborted
      }
      this.ended = true;
      for (const w of this.waiters.splice(0)) w(null);
    })();
  }

  private push(m: Json) {
    const w = this.waiters.shift();
    if (w) w(m);
    else this.queue.push(m);
  }

  next(timeoutMs = 2000): Promise<Json | null> {
    const m = this.queue.shift();
    if (m) return Promise.resolve(m);
    if (this.ended) return Promise.resolve(null);
    return new Promise((resolve, reject) => {
      const t = setTimeout(() => {
        this.waiters.splice(this.waiters.indexOf(fn), 1);
        reject(new Error("timed out waiting for SSE message"));
      }, timeoutMs);
      const fn = (v: Json | null) => {
        clearTimeout(t);
        resolve(v);
      };
      this.waiters.push(fn);
    });
  }

  /** Resolves true if no message arrives within `ms`. */
  async quiet(ms: number): Promise<boolean> {
    if (this.queue.length > 0) return false;
    try {
      const m = await this.next(ms);
      if (m) this.queue.unshift(m);
      return m === null;
    } catch {
      return true;
    }
  }
}

async function listen(url: string, notifications: Json) {
  const controller = new AbortController();
  const { id, res } = await post(url, "subscriptions/listen", { notifications }, { signal: controller.signal });
  assert.equal(res.status, 200);
  assert.match(res.headers.get("content-type") ?? "", /^text\/event-stream/);
  return { id, reader: new SseReader(res.body!), close: () => controller.abort() };
}

const FORM_CAPS = { elicitation: { form: {} } };

function callTool(url: string, name: string, args: Json, opts: RpcOptions = {}, extra: Json = {}) {
  return rpc(url, "tools/call", { name, arguments: args, ...extra }, opts);
}

before(() => {
  execFileSync(process.execPath, [path.join(ROOT, "node_modules/typescript/bin/tsc"), "-p", "."], {
    cwd: ROOT,
    stdio: "inherit",
  });
});

describe("field-notes MCP server over HTTP", () => {
  let server: Server;
  let url: string;

  before(async () => {
    server = await startServer();
    url = server.url;
  });
  after(async () => {
    await stopServer(server);
  });

  describe("discovery and lists", () => {
    test("server/discover advertises versions, capabilities, identity and instructions", async () => {
      const { status, body } = await rpc(url, "server/discover");
      assert.equal(status, 200);
      const r = body.result;
      assert.equal(r.resultType, "complete");
      assert.deepEqual(r.supportedVersions, ["2026-07-28"]);
      assert.deepEqual(r.capabilities, { tools: {}, resources: { subscribe: true }, prompts: {} });
      assert.deepEqual(r._meta["io.modelcontextprotocol/serverInfo"], { name: "field-notes", version: "1.0.0" });
      assert.equal(
        r.instructions,
        "Field Notes stores short notes grouped into notebooks. Use add_note to save a note, read notes://index to see what exists.",
      );
      assert.equal(r.ttlMs, 300000);
      assert.equal(r.cacheScope, "public");
    });

    test("tools/list returns tools alphabetically with header mapping and output schema", async () => {
      const { body } = await rpc(url, "tools/list");
      const r = body.result;
      assert.deepEqual(
        r.tools.map((t: Json) => t.name),
        ["add_note", "delete_note", "reindex"],
      );
      const add = r.tools[0];
      assert.equal(add.inputSchema.type, "object");
      assert.equal(add.inputSchema.properties.notebook["x-mcp-header"], "Notebook");
      assert.deepEqual(add.inputSchema.required.sort(), ["body", "notebook", "title"]);
      assert.deepEqual(add.outputSchema.required.sort(), ["id", "notebook", "uri", "wordCount"]);
      assert.equal(r.ttlMs, 300000);
      assert.equal(r.cacheScope, "public");
      assert.equal(r.nextCursor, undefined);
      assert.ok(r._meta["io.modelcontextprotocol/serverInfo"]);
    });

    test("resources/list, templates and prompts/list are cacheable public lists", async () => {
      const res = (await rpc(url, "resources/list")).body.result;
      assert.deepEqual(res.resources, [
        { uri: "notes://index", name: "index", title: "All notes", mimeType: "application/json" },
      ]);
      assert.equal(res.ttlMs, 300000);
      assert.equal(res.cacheScope, "public");

      const tpl = (await rpc(url, "resources/templates/list")).body.result;
      assert.deepEqual(tpl.resourceTemplates, [
        { uriTemplate: "notes://notes/{id}", name: "note", title: "A single note", mimeType: "text/markdown" },
      ]);
      assert.equal(tpl.cacheScope, "public");

      const prompts = (await rpc(url, "prompts/list")).body.result;
      assert.equal(prompts.prompts.length, 1);
      assert.equal(prompts.prompts[0].name, "summarize_notebook");
      assert.deepEqual(
        prompts.prompts[0].arguments.map((a: Json) => [a.name, a.required]),
        [
          ["notebook", true],
          ["style", false],
        ],
      );
      assert.equal(prompts.ttlMs, 300000);
    });

    test("an unknown cursor is invalid params", async () => {
      const { body } = await rpc(url, "tools/list", { cursor: "bogus" });
      assert.equal(body.error.code, -32602);
    });
  });

  describe("resources", () => {
    test("reads a note as markdown, private and never fresh", async () => {
      const { body } = await rpc(url, "resources/read", { uri: "notes://notes/n1" });
      const r = body.result;
      assert.deepEqual(r.contents, [
        {
          uri: "notes://notes/n1",
          mimeType: "text/markdown",
          text: "# Standup\n\nDiscussed the release schedule and blockers.\n",
        },
      ]);
      assert.equal(r.ttlMs, 0);
      assert.equal(r.cacheScope, "private");
    });

    test("reads the index", async () => {
      const { body } = await rpc(url, "resources/read", { uri: "notes://index" });
      const c = body.result.contents[0];
      assert.equal(c.mimeType, "application/json");
      const index = JSON.parse(c.text);
      assert.deepEqual(index.slice(0, 3), [
        { id: "n1", notebook: "work", title: "Standup" },
        { id: "n2", notebook: "work", title: "Retro actions" },
        { id: "n3", notebook: "personal", title: "Groceries" },
      ]);
      assert.equal(body.result.cacheScope, "private");
      assert.equal(body.result.ttlMs, 0);
    });

    test("a missing resource is -32602 with the uri", async () => {
      const { body } = await rpc(url, "resources/read", { uri: "notes://notes/n999" });
      assert.equal(body.error.code, -32602);
      assert.deepEqual(body.error.data, { uri: "notes://notes/n999" });
      const other = await rpc(url, "resources/read", { uri: "file:///etc/passwd" });
      assert.equal(other.body.error.code, -32602);
    });
  });

  describe("prompts", () => {
    test("brief summary embeds each note of the notebook", async () => {
      const { body } = await rpc(url, "prompts/get", { name: "summarize_notebook", arguments: { notebook: "work" } });
      const msgs = body.result.messages;
      assert.equal(body.result.resultType, "complete");
      assert.deepEqual(msgs[0], {
        role: "user",
        content: { type: "text", text: 'Summarize the notes in the "work" notebook in two sentences.' },
      });
      assert.deepEqual(msgs[1], {
        role: "user",
        content: {
          type: "resource",
          resource: {
            uri: "notes://notes/n1",
            mimeType: "text/markdown",
            text: "# Standup\n\nDiscussed the release schedule and blockers.\n",
          },
        },
      });
      assert.equal(msgs[2].content.resource.uri, "notes://notes/n2");
      assert.ok(msgs.every((m: Json) => m.role === "user"));
    });

    test("detailed style and empty notebook", async () => {
      const { body } = await rpc(url, "prompts/get", {
        name: "summarize_notebook",
        arguments: { notebook: "nothing-here", style: "detailed" },
      });
      assert.deepEqual(body.result.messages, [
        {
          role: "user",
          content: {
            type: "text",
            text: 'Summarize the notes in the "nothing-here" notebook in detail, one paragraph per note.',
          },
        },
      ]);
    });

    test("bad style, missing notebook and unknown prompt are invalid params", async () => {
      for (const params of [
        { name: "summarize_notebook", arguments: { notebook: "work", style: "haiku" } },
        { name: "summarize_notebook", arguments: {} },
        { name: "summarize_notebook" },
        { name: "nope", arguments: { notebook: "work" } },
      ]) {
        const { body } = await rpc(url, "prompts/get", params);
        assert.equal(body.error?.code, -32602, JSON.stringify(params));
      }
    });
  });

  describe("add_note", () => {
    test("creates a note and returns structured output plus text", async () => {
      const { status, body } = await callTool(url, "add_note", {
        notebook: "ideas",
        title: "Launch",
        body: "  ship   it\tnow ",
      });
      assert.equal(status, 200);
      const r = body.result;
      assert.equal(r.resultType, "complete");
      assert.notEqual(r.isError, true);
      assert.match(r.structuredContent.id, /^n\d+$/);
      assert.deepEqual(r.structuredContent, {
        id: r.structuredContent.id,
        uri: `notes://notes/${r.structuredContent.id}`,
        notebook: "ideas",
        wordCount: 3,
      });
      assert.deepEqual(JSON.parse(r.content[0].text), r.structuredContent);
      const read = await rpc(url, "resources/read", { uri: r.structuredContent.uri });
      assert.equal(read.body.result.contents[0].text, "# Launch\n\n  ship   it\tnow \n");
    });

    test("invalid arguments are tool execution errors", async () => {
      const cases: Json[] = [
        { notebook: "work", title: "", body: "x" },
        { notebook: "work", body: "x" },
        { notebook: "bad name!", title: "t", body: "x" },
        { notebook: "work", title: "t".repeat(201), body: "x" },
        { notebook: "work", title: 5, body: "x" },
        { notebook: "work", title: "t" },
        { notebook: "x".repeat(65), title: "t", body: "" },
      ];
      for (const args of cases) {
        const { status, body } = await callTool(url, "add_note", args);
        assert.equal(status, 200);
        assert.equal(body.result?.isError, true, JSON.stringify(args));
        assert.match(body.result.content[0].text, /Invalid arguments for add_note/);
      }
      const ok = await callTool(url, "add_note", { notebook: "work", title: "t".repeat(200), body: "" });
      assert.equal(ok.body.result.structuredContent.wordCount, 0);
    });

    test("Mcp-Param-Notebook header must be present and match the body", async () => {
      const args = { notebook: "work", title: "Hdr", body: "b" };
      const missing = await callTool(url, "add_note", args, { headers: { "Mcp-Param-Notebook": undefined } });
      assert.equal(missing.status, 400);
      assert.equal(missing.body.error.code, -32020);

      const wrong = await callTool(url, "add_note", args, { headers: { "Mcp-Param-Notebook": "personal" } });
      assert.equal(wrong.status, 400);
      assert.equal(wrong.body.error.code, -32020);

      const extra = await callTool(
        url,
        "add_note",
        { title: "t", body: "b" },
        { headers: { "Mcp-Param-Notebook": "work" } },
      );
      assert.equal(extra.status, 400);
      assert.equal(extra.body.error.code, -32020);

      const b64 = await callTool(url, "add_note", args, {
        headers: { "Mcp-Param-Notebook": `=?base64?${Buffer.from("work").toString("base64")}?=` },
      });
      assert.equal(b64.status, 200);
      assert.equal(b64.body.result.structuredContent.notebook, "work");

      const badB64 = await callTool(url, "add_note", args, { headers: { "Mcp-Param-Notebook": "=?base64?***?=" } });
      assert.equal(badB64.body.error.code, -32020);
    });
  });

  describe("delete_note", () => {
    async function createNote(title: string): Promise<string> {
      const { body } = await callTool(url, "add_note", { notebook: "tmp", title, body: "x" });
      return body.result.structuredContent.id;
    }

    test("unknown note is a tool execution error", async () => {
      const { body } = await callTool(url, "delete_note", { id: "n999" }, { caps: FORM_CAPS });
      assert.equal(body.result.isError, true);
      assert.equal(body.result.content[0].text, "Note n999 not found");
    });

    test("requires the form elicitation capability", async () => {
      const id = await createNote("Needs caps");
      for (const caps of [{}, { elicitation: { url: {} } }]) {
        const { status, body } = await callTool(url, "delete_note", { id }, { caps });
        assert.equal(status, 400);
        assert.equal(body.error.code, -32021);
        assert.ok(body.error.data.requiredCapabilities.elicitation);
      }
      // An empty elicitation object means form mode.
      const { body } = await callTool(url, "delete_note", { id }, { caps: { elicitation: {} } });
      assert.equal(body.result.resultType, "input_required");
    });

    test("asks for confirmation, then deletes on confirm: true", async () => {
      const id = await createNote("Doomed");
      const first = await callTool(url, "delete_note", { id }, { caps: FORM_CAPS });
      const r = first.body.result;
      assert.equal(r.resultType, "input_required");
      assert.equal(typeof r.requestState, "string");
      const [key, req] = Object.entries(r.inputRequests as Json)[0]!;
      assert.equal(req.method, "elicitation/create");
      assert.equal(req.params.mode, "form");
      assert.equal(req.params.message, 'Delete note "Doomed"?');
      assert.deepEqual(req.params.requestedSchema.required, ["confirm"]);
      assert.equal(req.params.requestedSchema.properties.confirm.type, "boolean");
      assert.deepEqual(Object.keys(req.params.requestedSchema.properties), ["confirm"]);

      // Still there until confirmed.
      assert.ok((await rpc(url, "resources/read", { uri: `notes://notes/${id}` })).body.result);

      const retry = await callTool(
        url,
        "delete_note",
        { id },
        { caps: FORM_CAPS },
        {
          inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
          requestState: r.requestState,
        },
      );
      assert.equal(retry.body.result.resultType, "complete");
      assert.deepEqual(retry.body.result.content, [{ type: "text", text: `Deleted note ${id}` }]);
      const gone = await rpc(url, "resources/read", { uri: `notes://notes/${id}` });
      assert.equal(gone.body.error.code, -32602);
    });

    test("decline, cancel and confirm: false keep the note", async () => {
      const id = await createNote("Survivor");
      for (const answer of [
        { action: "decline" },
        { action: "cancel" },
        { action: "accept", content: { confirm: false } },
      ]) {
        const first = await callTool(url, "delete_note", { id }, { caps: FORM_CAPS });
        const { requestState, inputRequests } = first.body.result;
        const key = Object.keys(inputRequests)[0]!;
        const retry = await callTool(
          url,
          "delete_note",
          { id },
          { caps: FORM_CAPS },
          { inputResponses: { [key]: answer }, requestState },
        );
        assert.notEqual(retry.body.result.isError, true);
        assert.deepEqual(retry.body.result.content, [{ type: "text", text: "Deletion cancelled" }]);
      }
      assert.ok((await rpc(url, "resources/read", { uri: `notes://notes/${id}` })).body.result);
    });

    test("confirmation cannot be forged, modified, or reused for another note", async () => {
      const a = await createNote("A");
      const b = await createNote("B");
      const first = await callTool(url, "delete_note", { id: a }, { caps: FORM_CAPS });
      const { requestState, inputRequests } = first.body.result;
      const key = Object.keys(inputRequests)[0]!;
      const yes = { [key]: { action: "accept", content: { confirm: true } } };

      const other = await callTool(url, "delete_note", { id: b }, { caps: FORM_CAPS }, { inputResponses: yes, requestState });
      assert.ok(other.body.error, "state for A must not delete B");

      const [data, sig] = (requestState as string).split(".");
      const payload = JSON.parse(Buffer.from(data!, "base64url").toString());
      payload.bind.id = b;
      const tampered = `${Buffer.from(JSON.stringify(payload)).toString("base64url")}.${sig}`;
      const t = await callTool(url, "delete_note", { id: b }, { caps: FORM_CAPS }, { inputResponses: yes, requestState: tampered });
      assert.ok(t.body.error, "tampered state must be rejected");

      const forged = await callTool(url, "delete_note", { id: b }, { caps: FORM_CAPS }, { inputResponses: yes, requestState: "forged" });
      assert.ok(forged.body.error);

      // Answer without any state: server asks again instead of deleting.
      const noState = await callTool(url, "delete_note", { id: b }, { caps: FORM_CAPS }, { inputResponses: yes });
      assert.equal(noState.body.result.resultType, "input_required");

      for (const id of [a, b]) {
        assert.ok((await rpc(url, "resources/read", { uri: `notes://notes/${id}` })).body.result, id);
