      assert.match(r.contentType, /^text\/event-stream/);
      const progress = r.messages.filter((m) => m.method === "notifications/progress");
      assert.deepEqual(
        progress.map((m) => m.params),
        [1, 2, 3].map((k) => ({ progressToken: "tok-1", progress: k, total: 3, message: `Indexed ${k}/3` })),
      );
      assert.deepEqual(r.response.result.content, [{ type: "text", text: "Reindex complete: 3 steps" }]);
      assert.equal(r.messages.at(-1)!.id, r.id);
    });

    test("defaults and plain JSON without a progress token", async () => {
      const r = await rpcAll(url, "tools/call", { name: "reindex", arguments: { delayMs: 0 } });
      assert.match(r.contentType, /^application\/json/);
      assert.equal(r.response.result.content[0].text, "Reindex complete: 5 steps");
    });

    test("out-of-range arguments are tool execution errors", async () => {
      for (const args of [{ steps: 0 }, { steps: 21 }, { steps: 2.5 }, { delayMs: -1 }, { delayMs: 1001 }, { steps: "3" }]) {
        const { body } = await callTool(url, "reindex", args);
        assert.equal(body.result?.isError, true, JSON.stringify(args));
      }
    });

    test("stops working when the client disconnects", async () => {
      const controller = new AbortController();
      const { res } = await post(
        url,
        "tools/call",
        { name: "reindex", arguments: { steps: 20, delayMs: 100 } },
        { metaExtra: { progressToken: 7 }, signal: controller.signal },
      );
      const reader = new SseReader(res.body!);
      const firstMsg = await reader.next(3000);
      assert.equal(firstMsg!.method, "notifications/progress");
      controller.abort();
      const deadline = Date.now() + 3000;
      while (!/reindex: request .* cancelled/.test(server.stderr()) && Date.now() < deadline) {
        await new Promise((r) => setTimeout(r, 50));
      }
      assert.match(server.stderr(), /reindex: request .* cancelled after \d+\/20 steps/);
    });
  });

  describe("subscriptions", () => {
    test("watchers are told only about the URIs they watch", async () => {
      const indexWatcher = await listen(url, {
        resourceSubscriptions: ["notes://index", "notes://notes/n2", "https://example.com/x"],
        toolsListChanged: true,
      });
      const n3Watcher = await listen(url, { resourceSubscriptions: ["notes://notes/n3"] });
      try {
        const ack = await indexWatcher.reader.next();
        assert.equal(ack!.method, "notifications/subscriptions/acknowledged");
        assert.equal(ack!.params._meta["io.modelcontextprotocol/subscriptionId"], indexWatcher.id);
        assert.deepEqual(ack!.params.notifications, {
          resourceSubscriptions: ["notes://index", "notes://notes/n2"],
        });
        const ack2 = await n3Watcher.reader.next();
        assert.equal(ack2!.method, "notifications/subscriptions/acknowledged");

        await callTool(url, "add_note", { notebook: "sub", title: "New", body: "b" });
        const upd = await indexWatcher.reader.next();
        assert.deepEqual(upd, {
          jsonrpc: "2.0",
          method: "notifications/resources/updated",
          params: {
            _meta: { "io.modelcontextprotocol/subscriptionId": indexWatcher.id },
            uri: "notes://index",
          },
        });
        assert.ok(await n3Watcher.reader.quiet(200), "n3 watcher must not hear about index changes");

        // Delete n2 via the confirmation flow.
        const first = await callTool(url, "delete_note", { id: "n2" }, { caps: FORM_CAPS });
        const key = Object.keys(first.body.result.inputRequests)[0]!;
        const del = await callTool(
          url,
          "delete_note",
          { id: "n2" },
          { caps: FORM_CAPS },
          {
            inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
            requestState: first.body.result.requestState,
          },
        );
        assert.equal(del.body.result.content[0].text, "Deleted note n2");
        const uris = [(await indexWatcher.reader.next())!.params.uri, (await indexWatcher.reader.next())!.params.uri];
        assert.deepEqual(uris.sort(), ["notes://index", "notes://notes/n2"]);
        assert.ok(await n3Watcher.reader.quiet(200));
      } finally {
        indexWatcher.close();
        n3Watcher.close();
      }
    });

    test("listen without a notifications filter is invalid params", async () => {
      const { body } = await rpc(url, "subscriptions/listen", {});
      assert.equal(body.error.code, -32602);
    });
  });

  describe("transport and protocol validation", () => {
    test("unsupported protocol version", async () => {
      const { status, body } = await rpc(url, "tools/list", {}, {
        headers: { "MCP-Protocol-Version": "2025-11-25" },
        rawParams: { _meta: { ...meta(), "io.modelcontextprotocol/protocolVersion": "2025-11-25" } },
      });
      assert.equal(status, 400);
      assert.equal(body.error.code, -32022);
      assert.deepEqual(body.error.data, { supported: ["2026-07-28"], requested: "2025-11-25" });
    });

    test("initialize from a legacy client names the supported versions", async () => {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json, text/event-stream" },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "initialize",
          params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "old", version: "1" } },
        }),
      });
      assert.equal(res.status, 400);
      const body = await res.json();
      assert.equal(body.error.code, -32022);
      assert.deepEqual(body.error.data.supported, ["2026-07-28"]);
    });

    test("missing required _meta fields are -32602 with 400", async () => {
      const noMeta = await rpc(url, "tools/list", {}, { rawParams: {} });
      assert.equal(noMeta.status, 400);
      assert.equal(noMeta.body.error.code, -32602);
      const noCaps = await rpc(url, "tools/list", {}, {
        rawParams: { _meta: { "io.modelcontextprotocol/protocolVersion": VERSION } },
